/** Whether a path is one of the personal model routes. */
export const handles = (path) => path === PERSONAL_MODEL_ROUTE || path === PERSONAL_MODEL_TEST_ROUTE || path === PERSONAL_MODEL_SHAPE_ROUTE ||
    path === CODEX_LINK_ROUTE || path === JEV_ROUTE;
