const decodeJudgment = Schema.decodeUnknownEffect(Schema.fromJsonString(Schema.Struct({ state: Schema.Json, questions: Schema.Record(Schema.String, Schema.Json) })));
/** Check Access's judgment: one question with an obvious answer. */
const JEV_CHECK = { state: { ok: true }, questions: { ok: Classifier.boolean({ instructions: "Is ok true?" }) } };
